layer.css:
[data-ryt="footer"] { color: var(--ryt-text); border-top: 1px solid rgb(139, 137, 130); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="pitch"] { color: rgb(94, 98, 107); border-left: 1px solid rgb(139, 137, 130); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(94, 98, 107); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 16px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 14px; font-weight: 650; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; position: relative }
[data-ryt="header"] { border-top: 1px solid rgb(216, 212, 202); border-bottom: 1px solid rgb(216, 212, 202); box-shadow: rgba(17, 19, 24, 0.08) 0px 8px 24px 0px }
[data-ryt="button"] { color: var(--ryt-bg); background-color: var(--ryt-text); border-radius: 8px; font-family: var(--ryt-font-body); font-weight: 800; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 5.6px; padding-right: 12px; padding-bottom: 5.6px; padding-left: 12px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-text); border-bottom: 1px solid var(--ryt-text); border-radius: 0px; font-weight: 800; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 56px; font-weight: 500; font-style: normal; line-height: 0.94; letter-spacing: -3.2256px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a::after { content: ""; display: block; position: absolute; width: 100%; height: 2px; color: var(--ryt-text); background-color: rgb(36, 85, 214); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-body); font-size: 14px; font-weight: 650; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: opacity 0.18s; -webkit-text-fill-color: var(--ryt-text); bottom: -6.08px; left: 0px }
